import * as React from "react";
import { cn } from "@/lib/utils";

export interface PullToRefreshIndicatorProps {
  /** Visual pull distance from `usePullToRefresh` (px). */
  pullDistance: number;
  /** True while the refresh is in flight. */
  isRefreshing: boolean;
  /** Distance at which a release triggers refresh; drives the reveal. Default 64. */
  threshold?: number;
  className?: string;
}

/**
 * Visual companion to `usePullToRefresh`: a frosted pill with a circular spinner
 * that slides down from the top edge as the user pulls and spins while
 * refreshing. Fixed and centered (the Toast positioning recipe), below any
 * top safe-area inset; mobile-oriented (the gesture is touch-only). Purely
 * decorative (`aria-hidden`) -- the hook's `announce()` covers screen readers,
 * so there is no duplicate live region here. Motion is handled by the global
 * reduced-motion stylesheet.
 */
export const PullToRefreshIndicator = React.forwardRef<HTMLDivElement, PullToRefreshIndicatorProps>(function PullToRefreshIndicator({
  pullDistance,
  isRefreshing,
  threshold = 64,
  className,
}, ref) {
  const active = isRefreshing || pullDistance > 0;
  const progress = Math.min(1, pullDistance / threshold);
  const translateY = isRefreshing ? threshold : pullDistance;

  return (
    <div
      ref={ref}
      aria-hidden
      className={cn(
        "pointer-events-none fixed inset-x-0 top-0 z-50 flex justify-center safe-top",
        className
      )}
      style={{
        transform: `translateY(${Math.max(0, translateY - 8)}px)`,
        opacity: active ? 1 : 0,
        transition: active ? undefined : "opacity 150ms ease, transform 150ms ease",
      }}
    >
      <div className="mt-2 flex h-9 w-9 items-center justify-center rounded-full border border-[var(--color-border-light)] bg-[var(--color-surface-light)] shadow-md dark:border-[var(--color-border-dark)] dark:bg-[var(--color-surface-dark)]">
        <span
          className={cn(
            "block h-5 w-5 rounded-full border-2 border-[var(--color-accent-500)] border-t-transparent",
            isRefreshing && "animate-spin"
          )}
          style={
            isRefreshing
              ? undefined
              : { transform: `rotate(${progress * 270}deg)`, opacity: 0.35 + progress * 0.65 }
          }
        />
      </div>
    </div>
  );
});

PullToRefreshIndicator.displayName = "PullToRefreshIndicator";
